// src/features/ecosystem/map/geometry.ts
var inBox = (b, tx, ty) => tx >= b.x0 && tx <= b.x1 && ty >= b.y0 && ty <= b.y1;
function areaView(snapshot, areaId) {
  const area = snapshot.areas[areaId];
  if (!area) return null;
  const w = area.window;
  const names = Object.entries(snapshot.bits);
  const inWindow = (tx, ty) => Number.isInteger(tx) && Number.isInteger(ty) && tx >= w.minTx && tx <= w.maxTx && ty >= w.minTy && ty <= w.maxTy;
  return {
    area,
    inWindow,
    flags(tx, ty) {
      if (!inWindow(tx, ty)) return /* @__PURE__ */ new Set(["blocked"]);
      const i = (tx - w.minTx) * 3;
      const mask = parseInt(area.rows[ty - w.minTy].slice(i, i + 3), 16);
      return new Set(names.filter(([, bit]) => mask & 1 << bit).map(([name]) => name));
    },
    subzoneAt(tx, ty) {
      return area.subzones.find((z) => inBox(z.box, tx, ty))?.id ?? null;
    }
  };
}

